<?php require_once "../../config/auth.php";header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="billing_invoices.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,['Invoice','Date','Customer','Type','Method','Subtotal','GST','Grand Total','Status']);$q=$pdo->query("SELECT b.invoice_no,b.invoice_date,c.company_name,b.billing_type,b.billing_method,b.subtotal,b.gst_amount,b.grand_total,b.status FROM billing b LEFT JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC");while($r=$q->fetch(PDO::FETCH_NUM))fputcsv($o,$r);fclose($o);exit;
